android.extraProguardRules:
# Nitro core and quick-crypto: C++ reaches these classes and members by name (neither ships rules).
-keep class com.margelo.** { *; }
# fbjni finds hybrid holders by the field name mHybridData and builds them through a (HybridData) constructor.
-keepclassmembers class * { com.facebook.jni.HybridData mHybridData; }
-keepclassmembers class * { <init>(com.facebook.jni.HybridData); }
# expo-modules-core and expo-sqlite: C++ constructs these exceptions by constructor signature.
-keepclassmembers class expo.modules.kotlin.exception.JavaScriptEvaluateException { <init>(java.lang.String, java.lang.String); }
-keepclassmembers class expo.modules.sqlite.SQLiteErrorException { <init>(java.lang.String); }
-keepclassmembers class expo.modules.sqlite.InvalidConvertibleException { <init>(java.lang.String); }
# expo-modules-core: error codes sent to JS are derived from the exception class name.
-keepnames class * extends expo.modules.kotlin.exception.CodedException
# expo-modules-core: loaded with Class.forName and patched by reflection at startup.
-keep class expo.modules.ExpoModulesPackageList { public *; }
-keep class inline.modules.ExpoInlineModulesList { public *; }
-keepclassmembers class com.facebook.react.ReactActivity { com.facebook.react.ReactActivityDelegate mDelegate; }
-keepclassmembers class com.facebook.react.ReactActivityDelegate { com.facebook.react.ReactDelegate mReactDelegate; }
# expo-camera probes for ML Kit with Class.forName; a renamed class turns QR scanning off.
-keepnames class com.google.mlkit.vision.barcode.BarcodeScanning
# Fresco (React Native <Image>) creates its memory pools through reflected constructors.
-keepclassmembers class com.facebook.imagepipeline.memory.*MemoryChunkPool { <init>(...); }
